// ═══ Natural ordering (Comparable) ═══
TreeMap<String, Integer> map = new TreeMap<>();
map.put("CUR3001", 3); map.put("SAV2001", 1); map.put("FD4001", 2);
// String implements Comparable → sorted alphabetically!
// Keys: CUR3001, FD4001, SAV2001

// ═══ Custom Comparator ═══
TreeMap<String, Integer> reversed = new TreeMap<>(Comparator.reverseOrder());
reversed.put("CUR3001", 3); reversed.put("SAV2001", 1);
// Keys: SAV2001, CUR3001 (reverse!)

// ═══ No Comparable + no Comparator → ClassCastException! ═══
class Account { String id; }  // does NOT implement Comparable!
TreeMap<Account, String> bad = new TreeMap<>();
// bad.put(new Account(), "val");  → ClassCastException!
// TreeMap tries: ((Comparable) key).compareTo(other) → Account is NOT Comparable!

// FIX: provide Comparator
TreeMap<Account, String> good = new TreeMap<>(Comparator.comparing(a -> a.id));
good.put(acc1, "Rajesh");  // ✅ works! Comparator used instead of Comparable.
