package com.bank.treemap;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class TreeMapComparableTest {

    static class NonComparableKey {
        String value;
        NonComparableKey(String value) { this.value = value; }
    }

    @Test
    void naturalOrder_comparable() {
        TreeMap<String, Integer> map = new TreeMap<>();
        map.put("C", 3); map.put("A", 1); map.put("B", 2);
        assertThat(new ArrayList<>(map.keySet())).containsExactly("A", "B", "C");
    }

    @Test
    void noComparable_throwsCCE() {
        TreeMap<NonComparableKey, String> map = new TreeMap<>();
        NonComparableKey key = new NonComparableKey("test");
        assertThatThrownBy(() -> map.put(key, "val"))
            .isInstanceOf(ClassCastException.class);
    }

    @Test
    void comparator_fixesCCE() {
        TreeMap<NonComparableKey, String> map = new TreeMap<>(
            Comparator.comparing(k -> k.value));
        map.put(new NonComparableKey("B"), "second");
        map.put(new NonComparableKey("A"), "first");
        assertThat(map.values()).containsExactly("first", "second");
    }
}
```

