  class Trade { /* NOT Comparable */ }

  // WRONG — CCE at second put()
  Map<Trade,Settlement> bad = new TreeMap<>();
  bad.put(t1, s1);            // ok, nothing to compare
  bad.put(t2, s2);            // ClassCastException!

  // RIGHT — supply Comparator at construction
  Map<Trade,Settlement> good = new TreeMap<>(
      Comparator.comparing(Trade::getTradeDate)
                .thenComparing(Trade::getTradeId));
  good.put(t1, s1);
  good.put(t2, s2);          // compared via Comparator

  // internals: Red-Black tree, O(log n)
  //   compare() = comparator!=null ? comparator.compare
  //                                : ((Comparable)k).compareTo
